import csv
import math
import re
from datetime import datetime
from statistics import median


def parse_amount(raw: str) -> float:
    s = raw.strip()
    if s == "":
        return float("nan")

    is_negative = ("CR" in s) or ("-" in s) or (s.startswith("(") and s.endswith(")"))

    s = s.replace("C1", "").replace("C2", "")
    s = re.sub(r"[^0-9,.]", "", s)

    if s == "":
        return float("nan")

    has_comma = "," in s
    has_period = "." in s

    if has_comma and has_period:
        last_comma = s.rfind(",")
        last_period = s.rfind(".")
        if last_comma > last_period:
            decimal_sep, thousand_sep = ",", "."
        else:
            decimal_sep, thousand_sep = ".", ","
        s = s.replace(thousand_sep, "")
        if decimal_sep != ".":
            s = s.replace(decimal_sep, ".")
    elif has_comma:
        last_idx = s.rfind(",")
        digits_after = len(s) - last_idx - 1
        if digits_after == 2:
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    elif has_period:
        last_idx = s.rfind(".")
        digits_after = len(s) - last_idx - 1
        if digits_after != 2:
            s = s.replace(".", "")

    if s == "" or s == ".":
        return float("nan")

    value = float(s)
    if is_negative and value != 0:
        value = -value
    return value


def parse_notes(notes: str):
    items = None
    m = re.search(r"items=(-?\d+)", notes)
    if m:
        items = int(m.group(1))

    adj_pct = 0.0
    m = re.search(r"adj=([+-]?\d+(?:\.\d+)?)%", notes)
    if m:
        adj_pct = float(m.group(1)) / 100.0

    fee = 0.0
    m = re.search(r"fee=([+-]?\d+(?:\.\d+)?)", notes)
    if m:
        fee = float(m.group(1))

    waive = bool(re.search(r"waive=true", notes, re.IGNORECASE))

    return items, adj_pct, fee, waive


def main():
    with open("/app/dataset/data.csv", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        raw_rows = list(reader)

    parsed_rows = []
    for idx, row in enumerate(raw_rows):
        record_id = row["record_id"]
        event_time_str = row["event_time"].strip()
        region = row["region"].strip()
        channel = row["channel"].strip()
        amount_str = row["amount_str"]
        notes = row["notes"] or ""

        base_amount = parse_amount(amount_str)
        items, adj_pct, fee, waive = parse_notes(notes)

        if math.isnan(base_amount):
            net = float("nan")
        else:
            net = base_amount * (1 + adj_pct) + fee
            if waive:
                net = 0.0

        event_time = None
        if event_time_str != "":
            event_time = datetime.strptime(event_time_str, "%Y-%m-%dT%H:%M:%SZ")

        parsed_rows.append({
            "order": idx,
            "record_id": record_id,
            "event_time": event_time,
            "region": region,
            "channel": channel,
            "items": items,
            "net": net,
            "has_real_net": not math.isnan(net),
        })

    best_by_id = {}
    for r in parsed_rows:
        rid = r["record_id"]
        if r["event_time"] is None:
            continue
        current = best_by_id.get(rid)
        if current is None:
            best_by_id[rid] = r
            continue
        if r["event_time"] > current["event_time"]:
            best_by_id[rid] = r
        elif r["event_time"] == current["event_time"]:
            if r["has_real_net"] and not current["has_real_net"]:
                best_by_id[rid] = r
            elif r["has_real_net"] == current["has_real_net"]:
                if r["order"] < current["order"]:
                    best_by_id[rid] = r

    dedup_rows = list(best_by_id.values())

    q4_start = datetime(2025, 10, 1, 0, 0, 0)
    q4_end = datetime(2025, 12, 31, 23, 59, 59)

    filtered = []
    for r in dedup_rows:
        if r["event_time"] is None:
            continue
        if not (q4_start <= r["event_time"] <= q4_end):
            continue
        if r["channel"].strip().lower() == "phone":
            continue
        if not math.isfinite(r["net"]):
            continue
        filtered.append(r)

    groups = {}
    for r in filtered:
        month = r["event_time"].strftime("%Y-%m")
        key = (r["region"], month)
        groups.setdefault(key, []).append(r)

    for key, rows in groups.items():
        nets = [r["net"] for r in rows]
        med = median(nets)
        abs_dev = [abs(n - med) for n in nets]
        mad = median(abs_dev)
        for r in rows:
            if mad == 0:
                r["robust_z"] = 0.0
            else:
                r["robust_z"] = 0.6745 * (r["net"] - med) / mad

    for r in filtered:
        items_eff = r["items"] if r["items"] is not None else 1
        if items_eff < 1:
            items_eff = 1
        r["items_eff"] = items_eff
        r["anomaly_score"] = abs(r["robust_z"]) * math.log1p(items_eff)

    ranked = sorted(
        filtered,
        key=lambda r: (
            -r["anomaly_score"],
            -abs(r["robust_z"]),
            -r["event_time"].timestamp(),
            r["record_id"],
        ),
    )

    top10 = [r["record_id"] for r in ranked[:10]]
    return top10


def answer() -> list:
    return main()


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

